package hotel.documents;

import hotel.reservations.Reservation;
import hotel.rooms.Room;
import hotel.rooms.RoomType;
import java.math.BigDecimal;
import java.time.LocalDate;

/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
public record ReservationReceipt(
        String title,
        long reservationId,
        String guestName,
        String guestCpf,
        int roomNumber,
        RoomType roomType,
        LocalDate checkIn,
        LocalDate checkOut,
        int nights,
        BigDecimal subtotal,
        BigDecimal discount,
        BigDecimal total) {

    public ReservationReceipt(Reservation reservation, Room room) {
        this(
                "Comprovante de reserva",
                reservation.id(),
                reservation.guest().name(),
                reservation.guest().cpf(),
                room.number(),
                room.type(),
                reservation.checkIn(),
                reservation.checkOut(),
                reservation.price().nights(),
                reservation.price().subtotal(),
                reservation.price().discount(),
                reservation.price().total());
    }

    public String text() {
        StringBuilder text = new StringBuilder();
        text.append(title).append(" nº ").append(reservationId).append('\n');
        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
        text.append("Entrada: ").append(TextFormat.date(checkIn))
                .append(" | Saída: ").append(TextFormat.date(checkOut))
                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
        if (discount.signum() > 0) {
            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
        }
        text.append("Total: ").append(TextFormat.money(total)).append('\n');
        return text.toString();
    }
}
-- The inn's rooms. They rarely change, so they come with the schema.
CREATE TABLE rooms (
    number       integer PRIMARY KEY,
    type         text NOT NULL,
    capacity     integer NOT NULL CHECK (capacity > 0),
    nightly_rate numeric(10, 2) NOT NULL CHECK (nightly_rate > 0)
);

INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    (101, 'STANDARD', 2, 249.90),
    (102, 'STANDARD', 2, 249.90),
    (201, 'DELUXE', 3, 389.90),
    (202, 'DELUXE', 3, 389.90),
    (301, 'SUITE', 4, 579.90);

-- btree_gist lets one constraint compare the room number (equality) and the nights (overlap) together.
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE reservations (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    room_number integer NOT NULL REFERENCES rooms (number),
    guest_name  text NOT NULL,
    guest_email text NOT NULL,
    guest_cpf   text NOT NULL,
    check_in    date NOT NULL,
    check_out   date NOT NULL,
    guests      integer NOT NULL CHECK (guests >= 1),
    rate_plan   text NOT NULL,
    nights      integer NOT NULL,
    subtotal    numeric(10, 2) NOT NULL,
    discount    numeric(10, 2) NOT NULL,
    total       numeric(10, 2) NOT NULL,
    status      text NOT NULL,
    amount_paid numeric(10, 2) NOT NULL,
    refund      numeric(10, 2),
    CHECK (check_out > check_in),
    -- a room is never booked twice for the same night, even when two requests arrive at the same time
    CONSTRAINT reservations_no_double_booking
        EXCLUDE USING gist (room_number WITH =, daterange(check_in, check_out) WITH &&)
        WHERE (status <> 'CANCELLED')
);

-- every message the inn sent, so the front desk can check what each guest received
CREATE TABLE messages (
    id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    channel   text NOT NULL,
    recipient text NOT NULL,
    subject   text NOT NULL,
    body      text NOT NULL
);
