$1/; s/(    \@Test
    void aRoomCannotBeBookedTwice)/    \@Test
    void childrenTakeAPlaceInTheRoomButDoNotChangeThePrice() {
        Reservation withChildren = service.create(stayWithChildren(201, 2, 1));
        assertEquals(1, service.find(withChildren.id()).children());
        assertEquals(new BigDecimal("779.80"), withChildren.price().total());
        assertEquals(0, service.create(stay(101, "2027-04-10", "2027-04-12", 2, RatePlan.STANDARD)).children());

        assertEquals(ErrorCode.CAPACITY_EXCEEDED, errorOf(() -> service.create(stayWithChildren(202, 2, 2))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(stayWithChildren(202, 2, -1))));
    }

    \@Test
    void theReceiptShowsTheChildrenOnlyWhenThereAreAny() {
        Reservation with = service.create(stayWithChildren(201, 2, 2));
        Reservation without = service.create(stayWithChildren(202, 2, 0));
        service.confirm(with.id());
        service.confirm(without.id());

        assertTrue(service.receiptCopy(with.id()).text().contains("Quarto: 201 (DELUXE)\nCrianças: 2\nEntrada"));
        assertTrue(!service.receiptCopy(without.id()).text().contains("Crianças"));
    }

