perl -0pi -e 's/(    \@Test
    void servesTheReportsAsCsv)/    \@Test
    void childrenAreOptionalAndComeBackInTheReservation() throws Exception {
        JsonNode without = json.readTree(post("/reservations", RESERVATION_JSON).body());
        assertEquals(0, without.get("children").asInt());

        String withChildren = RESERVATION_JSON.replace("\"guests\": 2,", "\"guests\": 2, \"children\": 1,")
                .replace("201", "202");
        long id = json.readTree(post("/reservations", withChildren).body()).get("id").asLong();
        assertEquals(1, json.readTree(get("/reservations/" + id).body()).get("children").asInt());

        assertEquals(422, post("/reservations", withChildren.replace("202", "301").replace("\"children\": 1", "\"children\": 3"))
                .statusCode());
        assertEquals(400, post("/reservations", withChildren.replace("\"children\": 1", "\"children\": -1")).statusCode());
    }

